def transform(grid):
    n=len(grid); out=[row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 2: continue
            orbit={(r,c),(c,r),(n-1-r,n-1-c),(n-1-c,n-1-r),
                   (r,n-1-c),(n-1-r,c),(c,n-1-r),(n-1-c,r)}
            vals={grid[rr][cc] for rr,cc in orbit if grid[rr][cc] != 2}
            if not vals: raise ValueError((r,c,'unresolved'))
            if len(vals)!=1: raise ValueError((r,c,vals))
            out[r][c]=vals.pop()
    return out
